// Types of the hub's operations for the SDK (`useLive`, `useCommand`, `client.api.call`).
// GENERATED BY HAND FOR THE PoC from base/schemas.py and plan §4.5; V3 generates this file from
// `/api/openapi.json` (keyed by operation_id = operation name) and CI checks it is current.
// Keep it in step with `./generated/operations.json`. One input per operation (ninja's parity):
// no path parameters, so the item `id` travels in the input — query string (GET) or body (POST).
import type { SessionMe } from '@erplora/ui/shell';

// ── base ─────────────────────────────────────────────────────────────────────────────────────

/** `base.SessionMeIn`: no parameters. */
export type SessionMeIn = Record<string, never>;

/** `base.SessionMeOut`: what the shell reads (`SessionMe`) plus the scope it was resolved for. */
export interface SessionMeOut extends SessionMe {
  scope: { kind: string; key: string };
}

// ── demo (plan §4.5; apps/demo/schemas.py) ───────────────────────────────────────────────────

export type ItemStatus = 'open' | 'done';

/** A page of a paginated list (`limit` ≤ 100, stable order with `id` as tie-break). */
export interface Page<T> {
  rows: T[];
  total: number;
  limit: number;
  offset: number;
}

export interface ItemListIn {
  search?: string;
  status?: ItemStatus;
  limit?: number;
  offset?: number;
}

export interface ItemOut {
  id: string;
  name: string;
  status: ItemStatus;
  note: string;
  line_count: number;
  /** ISO 8601. */
  updated_at: string;
}

/** `qty` is a `Decimal`: a JSON string on the way out (`"2.500"`). */
export interface ItemLineOut {
  id: string;
  text: string;
  qty: string;
  position: number;
  client_line_id: string | null;
}

export interface ItemDetailOut extends ItemOut {
  lines: ItemLineOut[];
}

export interface ItemStatsOut {
  total: number;
  open: number;
  done: number;
  lines: number;
}

export interface ItemRef {
  id: string;
}

export interface ItemIn {
  name: string;
  status?: ItemStatus;
  note?: string;
}

/** Only the fields sent change. */
export interface ItemPatchIn extends ItemRef {
  name?: string;
  status?: ItemStatus;
  note?: string;
}

/** `id` is the item's. `client_line_id` makes `demo.item.add_line` idempotent (one line per id and item). */
export interface LineIn extends ItemRef {
  text: string;
  /** A `Decimal` (> 0, up to 3 decimals): a number or its string. */
  qty: number | string;
  client_line_id?: string;
}

export interface DeletedOut {
  id: string;
}

declare module '@erplora/ui/sdk' {
  interface Operations {
    'base.session.me': { input: SessionMeIn; output: SessionMeOut };
    'demo.item.list': { input: ItemListIn; output: Page<ItemOut> };
    'demo.item.detail': { input: ItemRef; output: ItemDetailOut };
    'demo.item.stats': { input: Record<string, never>; output: ItemStatsOut };
    'demo.item.create': { input: ItemIn; output: ItemDetailOut };
    'demo.item.update': { input: ItemPatchIn; output: ItemDetailOut };
    'demo.item.delete': { input: ItemRef; output: DeletedOut };
    'demo.item.add_line': { input: LineIn; output: ItemDetailOut };
  }
}
